CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, oidc_issuer text NOT NULL, oidc_subject text NOT NULL, email text, display_name text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(oidc_issuer,oidc_subject));
CREATE TABLE memberships (org_id uuid REFERENCES organizations ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','member')), PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions (id bytea PRIMARY KEY CHECK(octet_length(id)=32), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, csrf_hash bytea NOT NULL, csrf_token text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oidc_flows (state_hash bytea PRIMARY KEY, pkce_verifier text NOT NULL, nonce text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE networks (id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,name text NOT NULL,ipv4_cidr cidr NOT NULL CHECK(family(ipv4_cidr)=4),ipv6_cidr cidr NOT NULL CHECK(family(ipv6_cidr)=6),root_anchor bytea NOT NULL CHECK(octet_length(root_anchor)=32),issuer_cert bytea CHECK(octet_length(issuer_cert)=178),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,name));
CREATE TABLE devices (id uuid PRIMARY KEY,network_id uuid NOT NULL REFERENCES networks ON DELETE CASCADE,name text NOT NULL,status text NOT NULL CHECK(status IN ('pending','approved','revoked')),noise_pubkey bytea NOT NULL CHECK(octet_length(noise_pubkey)=32),identity_pubkey bytea NOT NULL CHECK(octet_length(identity_pubkey)=32),bundle bytea NOT NULL CHECK(octet_length(bundle)=146),endpoints jsonb NOT NULL DEFAULT '[]',enrolled_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,revoked_at timestamptz,last_config_at timestamptz,UNIQUE(network_id,noise_pubkey),UNIQUE(network_id,identity_pubkey));
CREATE TABLE ip_allocations (network_id uuid NOT NULL REFERENCES networks ON DELETE CASCADE,device_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,family smallint NOT NULL CHECK(family IN (4,6)),addr inet NOT NULL,UNIQUE(network_id,addr),UNIQUE(network_id,device_id,family));
CREATE TABLE enrollment_tokens (id uuid PRIMARY KEY,network_id uuid NOT NULL REFERENCES networks ON DELETE CASCADE,token_hash bytea NOT NULL UNIQUE,created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,auto_approve bool NOT NULL DEFAULT false,consumed_at timestamptz,consumed_by_device uuid);
CREATE TABLE access_policies (id uuid PRIMARY KEY,network_id uuid NOT NULL REFERENCES networks ON DELETE CASCADE,src jsonb NOT NULL,dst jsonb NOT NULL,proto smallint NOT NULL CHECK(proto IN (0,1,6,17,58)),port_min int NOT NULL CHECK(port_min BETWEEN 0 AND 65535),port_max int NOT NULL CHECK(port_max BETWEEN port_min AND 65535),created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),CHECK(proto IN (6,17) OR (port_min=0 AND port_max=0)));
CREATE TABLE configuration_versions (id bigserial PRIMARY KEY,device_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,version bigint NOT NULL,config_hash bytea NOT NULL,not_before timestamptz NOT NULL,not_after timestamptz NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),issuer_serial bigint NOT NULL,UNIQUE(device_id,version));
CREATE TABLE audit_events (id bigserial PRIMARY KEY,at timestamptz NOT NULL DEFAULT now(),actor_kind text NOT NULL CHECK(actor_kind IN ('user','device','system')),actor_id text NOT NULL,org_id uuid,network_id uuid,action text NOT NULL,target text NOT NULL,detail jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_network_page ON audit_events(network_id,id DESC);
REVOKE UPDATE, DELETE, TRUNCATE ON audit_events FROM PUBLIC;
